// Moves the simulated operation forward by one minute.
// Each open case advances to its next stage with a per-stage probability.
// qa_review is deliberately slow, so it becomes the bottleneck.
const NEXT = { received: 'validated', validated: 'qa_review', qa_review: 'packed', packed: 'shipped', shipped: 'delivered' };
const P_ADVANCE = { received: 0.25, validated: 0.12, qa_review: 0.03, packed: 0.10, shipped: 0.02 };
const NEW_CASES = Number($env.SIMULATOR_NEW_CASES_PER_RUN ?? 3);

const { last_case_no, open_cases } = $input.first().json;
const events = [];

for (const c of open_cases) {
  if (NEXT[c.stage] && Math.random() < P_ADVANCE[c.stage]) {
    events.push({ case_id: c.case_id, stage: NEXT[c.stage], source: 'simulator' });
  }
}
for (let i = 1; i <= NEW_CASES; i++) {
  events.push({
    case_id: `ORD-${String(Number(last_case_no) + i).padStart(5, '0')}`,
    stage: 'received',
    source: 'simulator',
    payload: { channel: ['web', 'chat', 'phone'][Math.floor(Math.random() * 3)] },
  });
}
return [{ json: { events } }];
